  CONSTRAINT ck_gig_assignment_earnings CHECK ((estimated_earnings IS NULL OR estimated_earnings >= 0) AND (total_earnings IS NULL OR total_earnings >= 0) AND (projected_earnings IS NULL OR projected_earnings >= 0) AND ((estimated_earnings IS NULL AND total_earnings IS NULL AND projected_earnings IS NULL) OR earnings_currency_id IS NOT NULL)),
  CONSTRAINT ck_gig_assignment_completion CHECK ((NOT is_completed) OR completed_at IS NOT NULL),
  CONSTRAINT fk_gig_assignment_accepted_application FOREIGN KEY (gig_application_id, gig_request_id, gig_worker_profile_id, application_is_accepted) REFERENCES gig_application (id, gig_request_id, gig_worker_profile_id, is_accepted) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_assignment_request_tenant FOREIGN KEY (gig_request_id, organisation_id) REFERENCES gig_request (id, organisation_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_assignment_request_currency FOREIGN KEY (gig_request_id, currency_id) REFERENCES gig_request (id, currency_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_assignment_status_flag FOREIGN KEY (gig_assignment_status_id, is_completed) REFERENCES gig_assignment_status (id, is_completed) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_assignment_gig_rate_unit_id FOREIGN KEY (gig_rate_unit_id) REFERENCES gig_rate_unit (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_assignment_gig_reconcile_state_id FOREIGN KEY (gig_reconcile_state_id) REFERENCES gig_reconcile_state (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_assignment_earnings_currency_id FOREIGN KEY (earnings_currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_gig_assignment_handoff_ref (handoff_ref) WHERE handoff_ref IS NOT NULL AND deleted_at IS NULL,
  UNIQUE INDEX uq_gig_assignment_handoff_idempotency_key (handoff_idempotency_key) WHERE deleted_at IS NULL,
  INDEX idx_gig_assignment_gig_worker_profile_id_gig_assignment_status_id (gig_worker_profile_id, gig_assignment_status_id) WHERE deleted_at IS NULL,
  INDEX idx_gig_assignment_gig_request_id (gig_request_id) WHERE deleted_at IS NULL,
  INDEX idx_gig_assignment_organisation_id_window_start_at (organisation_id, window_start_at) WHERE deleted_at IS NULL,
  INDEX idx_gig_assignment_gig_reconcile_state_id_status_reconciled_at (gig_reconcile_state_id, status_reconciled_at) WHERE NOT is_completed AND deleted_at IS NULL,
  INDEX idx_gig_assignment_earnings_currency_id (earnings_currency_id)
);
