  CONSTRAINT fk_gig_assignment_status_history_from_gig_assignment_status_id FOREIGN KEY (from_gig_assignment_status_id) REFERENCES gig_assignment_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_assignment_status_history_to_gig_assignment_status_id FOREIGN KEY (to_gig_assignment_status_id) REFERENCES gig_assignment_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
