CREATE TABLE IF NOT EXISTS gig_availability_rule (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  gig_worker_profile_id UUID NOT NULL,
  gig_weekday_id UUID NOT NULL,
  local_start_time TIME NOT NULL,
  local_end_time TIME NOT NULL,
  effective_from_date DATE NOT NULL,
  effective_to_date DATE,
  CONSTRAINT pk_gig_availability_rule PRIMARY KEY (id),
  CONSTRAINT ck_gig_availability_rule_times CHECK (local_end_time > local_start_time),
  CONSTRAINT ck_gig_availability_rule_dates CHECK (effective_to_date IS NULL OR effective_to_date >= effective_from_date),
  CONSTRAINT fk_gig_availability_rule_gig_worker_profile_id FOREIGN KEY (gig_worker_profile_id) REFERENCES gig_worker_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_availability_rule_gig_weekday_id FOREIGN KEY (gig_weekday_id) REFERENCES gig_weekday (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_gig_availability_rule_gig_worker_profile_id_gig_weekday_id_local_start_time (gig_worker_profile_id, gig_weekday_id, local_start_time) WHERE effective_to_date IS NULL AND deleted_at IS NULL
);
