CREATE TABLE IF NOT EXISTS gig_availability_window (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  gig_worker_profile_id UUID NOT NULL,
  window_start_at TIMESTAMPTZ NOT NULL,
  window_end_at TIMESTAMPTZ NOT NULL,
  note STRING(300),
  CONSTRAINT pk_gig_availability_window PRIMARY KEY (id),
  CONSTRAINT ck_gig_availability_window_range CHECK (window_end_at > window_start_at),
  CONSTRAINT ck_gig_availability_window_grid CHECK ((extract(epoch FROM window_start_at)::INT8 % 900) = 0 AND (extract(epoch FROM window_end_at)::INT8 % 900) = 0),
  CONSTRAINT ck_gig_availability_window_max_length CHECK (window_end_at - window_start_at <= INTERVAL '31 days'),
  CONSTRAINT fk_gig_availability_window_gig_worker_profile_id FOREIGN KEY (gig_worker_profile_id) REFERENCES gig_worker_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  INDEX idx_gig_availability_window_gig_worker_profile_id_window_start_at (gig_worker_profile_id, window_start_at) WHERE deleted_at IS NULL
);
