  CONSTRAINT uq_gig_cancellation_gig_assignment_id UNIQUE (gig_assignment_id),
  CONSTRAINT ck_gig_cancellation_slots CHECK (slots_released_count >= 0),
  CONSTRAINT fk_gig_cancellation_gig_assignment_id FOREIGN KEY (gig_assignment_id) REFERENCES gig_assignment (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_cancellation_cancelled_by_gig_actor_party_id FOREIGN KEY (cancelled_by_gig_actor_party_id) REFERENCES gig_actor_party (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_cancellation_gig_cancellation_reason_id FOREIGN KEY (gig_cancellation_reason_id) REFERENCES gig_cancellation_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_gig_cancellation_cancelled_at (cancelled_at) WHERE slots_released_at IS NULL
);
