CREATE TABLE IF NOT EXISTS gig_dispute (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  gig_assignment_id UUID NOT NULL,
  raised_by_gig_actor_party_id UUID NOT NULL,
  raised_by_app_user_id UUID NOT NULL,
  gig_dispute_reason_id UUID NOT NULL,
  description STRING(3000) NOT NULL,
  disputed_amount DECIMAL(12,2),
  currency_id UUID,
  gig_dispute_status_id UUID NOT NULL,
  opened_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  resolved_at TIMESTAMPTZ,
  resolved_by_app_user_id UUID,
  resolution_summary STRING(2000),
  CONSTRAINT pk_gig_dispute PRIMARY KEY (id),
  CONSTRAINT ck_gig_dispute_amount CHECK ((disputed_amount IS NULL OR disputed_amount > 0) AND ((disputed_amount IS NULL) = (currency_id IS NULL))),
  CONSTRAINT ck_gig_dispute_resolved CHECK (resolved_at IS NULL OR resolved_at >= opened_at),
  CONSTRAINT fk_gig_dispute_gig_assignment_id FOREIGN KEY (gig_assignment_id) REFERENCES gig_assignment (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_dispute_raised_by_gig_actor_party_id FOREIGN KEY (raised_by_gig_actor_party_id) REFERENCES gig_actor_party (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_dispute_raised_by_app_user_id FOREIGN KEY (raised_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_dispute_gig_dispute_reason_id FOREIGN KEY (gig_dispute_reason_id) REFERENCES gig_dispute_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_dispute_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_dispute_gig_dispute_status_id FOREIGN KEY (gig_dispute_status_id) REFERENCES gig_dispute_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_dispute_resolved_by_app_user_id FOREIGN KEY (resolved_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_gig_dispute_gig_assignment_id (gig_assignment_id) WHERE deleted_at IS NULL,
  INDEX idx_gig_dispute_gig_dispute_status_id_opened_at (gig_dispute_status_id, opened_at) WHERE resolved_at IS NULL AND deleted_at IS NULL,
  INDEX idx_gig_dispute_raised_by_app_user_id (raised_by_app_user_id),
  INDEX idx_gig_dispute_currency_id (currency_id),
  INDEX idx_gig_dispute_resolved_by_app_user_id (resolved_by_app_user_id)
);
