  received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT pk_gig_earnings_snapshot PRIMARY KEY (id),
  CONSTRAINT uq_gig_earnings_snapshot_source_system_idempotency_key UNIQUE (source_system, idempotency_key),
  CONSTRAINT ck_gig_earnings_snapshot_amount CHECK (amount >= 0),
  CONSTRAINT ck_gig_earnings_snapshot_period CHECK (period_end_date IS NULL OR period_start_date IS NULL OR period_end_date >= period_start_date),
  CONSTRAINT fk_gig_earnings_snapshot_gig_worker_profile_id FOREIGN KEY (gig_worker_profile_id) REFERENCES gig_worker_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_earnings_snapshot_assignment_worker FOREIGN KEY (gig_assignment_id, gig_worker_profile_id) REFERENCES gig_assignment (id, gig_worker_profile_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_earnings_snapshot_gig_earnings_kind_id FOREIGN KEY (gig_earnings_kind_id) REFERENCES gig_earnings_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_earnings_snapshot_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_gig_earnings_snapshot_gig_assignment_id_gig_earnings_kind_id_as_of_at (gig_assignment_id, gig_earnings_kind_id, as_of_at DESC) WHERE gig_assignment_id IS NOT NULL,
  INDEX idx_gig_earnings_snapshot_gig_worker_profile_id_as_of_at (gig_worker_profile_id, as_of_at DESC),
  INDEX idx_gig_earnings_snapshot_as_of_at (as_of_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_gig_earnings_snapshot_currency_id (currency_id)
);
