CREATE TABLE IF NOT EXISTS gig_fulfilment_event (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  source_system STRING(32) NOT NULL,
  idempotency_key STRING(128) NOT NULL,
  gig_fulfilment_event_type_id UUID NOT NULL,
  handoff_ref STRING(128),
  gig_assignment_id UUID,
  occurred_at TIMESTAMPTZ NOT NULL,
  received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  schema_version INT2 NOT NULL DEFAULT 1,
  signature_valid BOOL NOT NULL DEFAULT true,
  payload JSONB NOT NULL,
  CONSTRAINT pk_gig_fulfilment_event PRIMARY KEY (id),
  CONSTRAINT uq_gig_fulfilment_event_source_system_idempotency_key UNIQUE (source_system, idempotency_key),
  CONSTRAINT ck_gig_fulfilment_event_signature CHECK (signature_valid),
  CONSTRAINT ck_gig_fulfilment_event_version CHECK (schema_version > 0),
  CONSTRAINT fk_gig_fulfilment_event_gig_fulfilment_event_type_id FOREIGN KEY (gig_fulfilment_event_type_id) REFERENCES gig_fulfilment_event_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_fulfilment_event_gig_assignment_id FOREIGN KEY (gig_assignment_id) REFERENCES gig_assignment (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_gig_fulfilment_event_gig_assignment_id_occurred_at (gig_assignment_id, occurred_at DESC) WHERE gig_assignment_id IS NOT NULL,
  INDEX idx_gig_fulfilment_event_handoff_ref (handoff_ref) WHERE handoff_ref IS NOT NULL,
  INDEX idx_gig_fulfilment_event_received_at (received_at) USING HASH WITH (bucket_count = 16)
) WITH (ttl_expiration_expression = '(created_at + INTERVAL ''395 days'')', ttl_job_cron = '@daily');
-- @@
CREATE TABLE IF NOT EXISTS gig_fulfilment_event_attempt (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
