  CONSTRAINT uq_gig_fulfilment_event_attempt_gig_fulfilment_event_id_attempt_no UNIQUE (gig_fulfilment_event_id, attempt_no),
  CONSTRAINT ck_gig_fulfilment_event_attempt_attempt CHECK (attempt_no > 0),
  CONSTRAINT fk_gig_fulfilment_event_attempt_gig_fulfilment_event_id FOREIGN KEY (gig_fulfilment_event_id) REFERENCES gig_fulfilment_event (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_fulfilment_event_attempt_gig_event_process_status_id FOREIGN KEY (gig_event_process_status_id) REFERENCES gig_event_process_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_gig_fulfilment_event_attempt_processed_at (processed_at) USING HASH WITH (bucket_count = 16)
);
