  CONSTRAINT fk_gig_invite_gig_invite_status_id FOREIGN KEY (gig_invite_status_id) REFERENCES gig_invite_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_invite_gig_application_id FOREIGN KEY (gig_application_id) REFERENCES gig_application (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  UNIQUE INDEX uq_gig_invite_gig_request_id_gig_worker_profile_id (gig_request_id, gig_worker_profile_id) WHERE deleted_at IS NULL,
  INDEX idx_gig_invite_gig_worker_profile_id_gig_invite_status_id (gig_worker_profile_id, gig_invite_status_id) WHERE deleted_at IS NULL,
  UNIQUE INDEX uq_gig_invite_gig_application_id (gig_application_id) WHERE gig_application_id IS NOT NULL AND deleted_at IS NULL,
