  CONSTRAINT fk_gig_payout_reference_assignment_worker FOREIGN KEY (gig_assignment_id, gig_worker_profile_id) REFERENCES gig_assignment (id, gig_worker_profile_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_payout_reference_gig_payout_status_id FOREIGN KEY (gig_payout_status_id) REFERENCES gig_payout_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_payout_reference_gig_payout_channel_id FOREIGN KEY (gig_payout_channel_id) REFERENCES gig_payout_channel (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_payout_reference_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_gig_payout_reference_gig_assignment_id (gig_assignment_id),
