CREATE TABLE IF NOT EXISTS gig_rating (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  gig_assignment_id UUID NOT NULL,
  gig_worker_profile_id UUID NOT NULL,
  organisation_id UUID NOT NULL,
  rater_app_user_id UUID NOT NULL,
  assignment_is_completed BOOL NOT NULL DEFAULT true,
  stars INT2 NOT NULL,
  quality_stars INT2,
  punctuality_stars INT2,
  communication_stars INT2,
  review_text STRING(2000),
  is_public BOOL NOT NULL DEFAULT true,
  worker_reply STRING(1000),
  CONSTRAINT pk_gig_rating PRIMARY KEY (id),
  CONSTRAINT ck_gig_rating_completed_flag CHECK (assignment_is_completed),
  CONSTRAINT ck_gig_rating_stars CHECK (stars BETWEEN 1 AND 5),
  CONSTRAINT ck_gig_rating_sub_stars CHECK ((quality_stars IS NULL OR quality_stars BETWEEN 1 AND 5) AND (punctuality_stars IS NULL OR punctuality_stars BETWEEN 1 AND 5) AND (communication_stars IS NULL OR communication_stars BETWEEN 1 AND 5)),
  CONSTRAINT fk_gig_rating_completed_assignment FOREIGN KEY (gig_assignment_id, assignment_is_completed) REFERENCES gig_assignment (id, is_completed) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_rating_assignment_worker FOREIGN KEY (gig_assignment_id, gig_worker_profile_id) REFERENCES gig_assignment (id, gig_worker_profile_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_rating_assignment_tenant FOREIGN KEY (gig_assignment_id, organisation_id) REFERENCES gig_assignment (id, organisation_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_rating_rater_app_user_id FOREIGN KEY (rater_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_gig_rating_gig_assignment_id (gig_assignment_id) WHERE deleted_at IS NULL,
  INDEX idx_gig_rating_gig_worker_profile_id_created_at (gig_worker_profile_id, created_at DESC) STORING (stars) WHERE is_public AND deleted_at IS NULL,
  INDEX idx_gig_rating_rater_app_user_id (rater_app_user_id)
);
