CREATE TABLE IF NOT EXISTS gig_time_off (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  gig_worker_profile_id UUID NOT NULL,
  gig_time_off_type_id UUID NOT NULL,
  time_off_start_at TIMESTAMPTZ NOT NULL,
  time_off_end_at TIMESTAMPTZ NOT NULL,
  reason STRING(300),
  CONSTRAINT pk_gig_time_off PRIMARY KEY (id),
  CONSTRAINT uq_gig_time_off_id_gig_worker_profile_id UNIQUE (id, gig_worker_profile_id),
  CONSTRAINT ck_gig_time_off_range CHECK (time_off_end_at > time_off_start_at),
  CONSTRAINT ck_gig_time_off_grid CHECK ((extract(epoch FROM time_off_start_at)::INT8 % 900) = 0 AND (extract(epoch FROM time_off_end_at)::INT8 % 900) = 0),
  CONSTRAINT ck_gig_time_off_max_length CHECK (time_off_end_at - time_off_start_at <= INTERVAL '31 days'),
  CONSTRAINT fk_gig_time_off_gig_worker_profile_id FOREIGN KEY (gig_worker_profile_id) REFERENCES gig_worker_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_time_off_gig_time_off_type_id FOREIGN KEY (gig_time_off_type_id) REFERENCES gig_time_off_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_gig_time_off_gig_worker_profile_id_time_off_start_at (gig_worker_profile_id, time_off_start_at) WHERE deleted_at IS NULL
);
