CREATE TABLE IF NOT EXISTS gig_timesheet_entry (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  gig_assignment_id UUID NOT NULL,
  gig_worker_profile_id UUID NOT NULL,
  check_in_at TIMESTAMPTZ NOT NULL,
  check_out_at TIMESTAMPTZ,
  gig_checkin_method_id UUID NOT NULL,
  check_in_latitude DECIMAL(9,6),
  check_in_longitude DECIMAL(9,6),
  geo_source_id UUID,
  break_minutes INT2 NOT NULL DEFAULT 0,
  is_approved BOOL NOT NULL DEFAULT false,
  approved_at TIMESTAMPTZ,
  external_entry_ref STRING(128),
  CONSTRAINT pk_gig_timesheet_entry PRIMARY KEY (id),
  CONSTRAINT ck_gig_timesheet_entry_range CHECK (check_out_at IS NULL OR check_out_at >= check_in_at),
  CONSTRAINT ck_gig_timesheet_entry_latitude CHECK (check_in_latitude IS NULL OR check_in_latitude BETWEEN -90 AND 90),
  CONSTRAINT ck_gig_timesheet_entry_longitude CHECK (check_in_longitude IS NULL OR check_in_longitude BETWEEN -180 AND 180),
  CONSTRAINT ck_gig_timesheet_entry_geo_pair CHECK ((check_in_latitude IS NULL) = (check_in_longitude IS NULL) AND (check_in_latitude IS NULL OR geo_source_id IS NOT NULL)),
  CONSTRAINT ck_gig_timesheet_entry_break CHECK (break_minutes BETWEEN 0 AND 1440),
  CONSTRAINT ck_gig_timesheet_entry_approval CHECK ((NOT is_approved) OR approved_at IS NOT NULL),
  CONSTRAINT fk_gig_timesheet_entry_assignment_worker FOREIGN KEY (gig_assignment_id, gig_worker_profile_id) REFERENCES gig_assignment (id, gig_worker_profile_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_timesheet_entry_gig_checkin_method_id FOREIGN KEY (gig_checkin_method_id) REFERENCES gig_checkin_method (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_timesheet_entry_geo_source_id FOREIGN KEY (geo_source_id) REFERENCES geo_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_gig_timesheet_entry_gig_assignment_id (gig_assignment_id) WHERE check_out_at IS NULL AND deleted_at IS NULL,
  INDEX idx_gig_timesheet_entry_gig_assignment_id_check_in_at (gig_assignment_id, check_in_at) WHERE deleted_at IS NULL,
  UNIQUE INDEX uq_gig_timesheet_entry_gig_assignment_id_external_entry_ref (gig_assignment_id, external_entry_ref) WHERE external_entry_ref IS NOT NULL AND deleted_at IS NULL,
  INDEX idx_gig_timesheet_entry_check_in_at (check_in_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_gig_timesheet_entry_geo_source_id (geo_source_id)
);
