CREATE TABLE IF NOT EXISTS gig_slot (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  gig_worker_profile_id UUID NOT NULL,
  gig_assignment_id UUID,
  gig_time_off_id UUID,
  slot_start_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT pk_gig_slot PRIMARY KEY (id),
  CONSTRAINT uq_gig_slot_gig_worker_profile_id_slot_start_at UNIQUE (gig_worker_profile_id, slot_start_at),
  CONSTRAINT ck_gig_slot_grid CHECK ((extract(epoch FROM slot_start_at)::INT8 % 900) = 0),
  CONSTRAINT ck_gig_slot_one_owner CHECK ((gig_assignment_id IS NULL) <> (gig_time_off_id IS NULL)),
  CONSTRAINT fk_gig_slot_gig_worker_profile_id FOREIGN KEY (gig_worker_profile_id) REFERENCES gig_worker_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_slot_assignment_worker FOREIGN KEY (gig_assignment_id, gig_worker_profile_id) REFERENCES gig_assignment (id, gig_worker_profile_id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_gig_slot_time_off_worker FOREIGN KEY (gig_time_off_id, gig_worker_profile_id) REFERENCES gig_time_off (id, gig_worker_profile_id) ON DELETE CASCADE ON UPDATE RESTRICT,
  INDEX idx_gig_slot_gig_assignment_id (gig_assignment_id) WHERE gig_assignment_id IS NOT NULL,
  INDEX idx_gig_slot_gig_time_off_id (gig_time_off_id) WHERE gig_time_off_id IS NOT NULL,
  INDEX idx_gig_slot_slot_start_at (slot_start_at) USING HASH WITH (bucket_count = 16)
) WITH (ttl_expiration_expression = '(slot_start_at + INTERVAL ''90 days'')', ttl_job_cron = '@daily');
